SET NAMES utf8mb4;
CREATE TABLE users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mobile VARCHAR(15) NOT NULL UNIQUE,name VARCHAR(120),locale CHAR(2) NOT NULL DEFAULT 'fa',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE otp_codes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mobile VARCHAR(15) NOT NULL,code_hash VARCHAR(255) NOT NULL,request_ip VARCHAR(45) NOT NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(mobile),INDEX(request_ip),INDEX(expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE companies (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,legal_name VARCHAR(220),national_id VARCHAR(30),economic_code VARCHAR(30),registration_no VARCHAR(30),phone VARCHAR(30),mobile VARCHAR(15),email VARCHAR(190),website VARCHAR(190),address TEXT,postal_code VARCHAR(20),logo_path VARCHAR(255),stamp_path VARCHAR(255),signature_path VARCHAR(255),brand_color VARCHAR(7) DEFAULT '#2563eb',default_tax DECIMAL(5,2) DEFAULT 0,quote_prefix VARCHAR(20) DEFAULT 'PF',next_quote_number BIGINT UNSIGNED DEFAULT 1,bank_info TEXT,default_terms TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_company_user FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE,INDEX(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE customers (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,type ENUM('person','business')DEFAULT 'business',name VARCHAR(220) NOT NULL,contact_name VARCHAR(180),mobile VARCHAR(15),phone VARCHAR(30),email VARCHAR(190),national_id VARCHAR(30),economic_code VARCHAR(30),registration_no VARCHAR(30),address TEXT,postal_code VARCHAR(20),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE,INDEX(company_id,name),INDEX(mobile)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE catalog_items (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,type ENUM('product','service')DEFAULT 'product',name VARCHAR(220) NOT NULL,sku VARCHAR(80),description TEXT,unit VARCHAR(40) DEFAULT 'عدد',last_price DECIMAL(18,2) NOT NULL DEFAULT 0,default_tax DECIMAL(5,2) DEFAULT 0,is_active TINYINT(1)DEFAULT 1,last_used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE,INDEX(company_id,name),INDEX(company_id,sku)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE quotes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NULL,quote_number VARCHAR(60) NOT NULL,status ENUM('draft','issued','cancelled','expired','accepted','rejected')DEFAULT 'draft',issue_date DATE NOT NULL,valid_until DATE NULL,currency VARCHAR(10)DEFAULT 'IRR',company_snapshot JSON NOT NULL,customer_snapshot JSON NOT NULL,subtotal DECIMAL(18,2)DEFAULT 0,discount_type ENUM('amount','percent')DEFAULT 'amount',discount_value DECIMAL(18,2)DEFAULT 0,discount_amount DECIMAL(18,2)DEFAULT 0,tax_amount DECIMAL(18,2)DEFAULT 0,total DECIMAL(18,2)DEFAULT 0,prepayment DECIMAL(18,2)DEFAULT 0,payable DECIMAL(18,2)DEFAULT 0,notes TEXT,terms TEXT,version INT UNSIGNED DEFAULT 1,issued_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE,FOREIGN KEY(company_id)REFERENCES companies(id),FOREIGN KEY(customer_id)REFERENCES customers(id)ON DELETE SET NULL,UNIQUE(company_id,quote_number),INDEX(user_id,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE quote_items (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quote_id BIGINT UNSIGNED NOT NULL,catalog_item_id BIGINT UNSIGNED NULL,sort_order INT UNSIGNED DEFAULT 0,type ENUM('product','service')DEFAULT 'product',name VARCHAR(220)NOT NULL,description TEXT,sku VARCHAR(80),unit VARCHAR(40),quantity DECIMAL(18,3)NOT NULL,unit_price DECIMAL(18,2)NOT NULL,discount_percent DECIMAL(5,2)DEFAULT 0,tax_percent DECIMAL(5,2)DEFAULT 0,line_subtotal DECIMAL(18,2)NOT NULL,line_total DECIMAL(18,2)NOT NULL,FOREIGN KEY(quote_id)REFERENCES quotes(id)ON DELETE CASCADE,FOREIGN KEY(catalog_item_id)REFERENCES catalog_items(id)ON DELETE SET NULL,INDEX(quote_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE price_history (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,catalog_item_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,price DECIMAL(18,2)NOT NULL,source_quote_id BIGINT UNSIGNED NULL,effective_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(catalog_item_id)REFERENCES catalog_items(id)ON DELETE CASCADE,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE,FOREIGN KEY(source_quote_id)REFERENCES quotes(id)ON DELETE SET NULL,INDEX(catalog_item_id,effective_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE audit_logs (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,company_id BIGINT UNSIGNED NULL,action VARCHAR(80)NOT NULL,entity_type VARCHAR(60)NOT NULL,entity_id BIGINT UNSIGNED NULL,before_data JSON NULL,after_data JSON NULL,ip VARCHAR(45),user_agent VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),INDEX(entity_type,entity_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
